    objectives: {"pt": <String>["Proteger o resgatista", "Restaurar ventilação alveolar", "Corrigir hipóxia", "Tratar acidose pela causa, não por números isolados"], "es": <String>["Proteger al rescatista", "Restaurar ventilación alveolar", "Corregir hipoxia", "Tratar acidosis por la causa, no por números aislados"]},
    drugsFirstLine: {"pt": <String>["Retirada da exposição por equipe com proteção respiratória adequada", "O₂ em alta concentração", "Ventilação BVM/intubação se ventilação espontânea for inadequada"], "es": <String>["Retiro de la exposición por equipo con protección respiratoria adecuada", "O₂ a alta concentración", "Ventilación BVM/intubación si la ventilación espontánea es inadecuada"]},
    drugsSecondLine: {"pt": <String>["Benzodiazepínico se convulsão", "Suporte hemodinâmico conforme fisiologia"], "es": <String>["Benzodiacepina si convulsión", "Soporte hemodinámico según fisiología"]},
    drugsConditional: {"pt": <String>["Bicarbonato não é antídoto; considerar apenas em acidemia extrema com indicação fisiológica específica enquanto ventilação é corrigida"], "es": <String>["Bicarbonato no es antídoto; considerarlo solo en acidemia extrema con indicación fisiológica específica mientras se corrige ventilación"]},
    drugsContraindicated: {"pt": <String>["Não entrar em espaço IDLH sem SCBA/treinamento", "Não fazer resgate impulsivo", "Não atribuir inconsciência apenas a 'falta de O₂' sem reconhecer hipercapnia"], "es": <String>["No ingresar a espacio IDLH sin SCBA/entrenamiento", "No realizar rescate impulsivo", "No atribuir inconsciencia solo a 'falta de O₂' sin reconocer hipercapnia"]},
    scenarios: {"pt": <String>["CASO-BASE — Trabalhador encontrado inconsciente em tanque de fermentação; colega relata cefaleia antes de colapsar.", "EVOLUÇÃO 1 — Gasometria: pH 7,05 e PaCO₂ 95 mmHg. O mecanismo principal é hipercapnia aguda.", "EVOLUÇÃO 2 — Após ventilação adequada, PaCO₂ e consciência melhoram rapidamente; reavaliar coexposições e lesões secundárias."], "es": <String>["CASO-BASE — Trabajador hallado inconsciente en tanque de fermentación; compañero refiere cefalea antes del colapso.", "EVOLUCIÓN 1 — Gasometría: pH 7,05 y PaCO₂ 95 mmHg. El mecanismo principal es hipercapnia aguda.", "EVOLUCIÓN 2 — Tras ventilación adecuada, PaCO₂ y conciencia mejoran rápidamente; reevaluar coexposiciones y lesiones secundarias."]},
    monitoring: {"pt": <String>["Ventilação/ETCO₂", "SpO₂", "pH/PaCO₂ seriados", "ECG/PA", "Neurológico"], "es": <String>["Ventilación/ETCO₂", "SpO₂", "pH/PaCO₂ seriados", "ECG/PA", "Neurológico"]},
