    differentialDiagnosis: {"pt": <String>["CO isolado", "Cianeto isolado", "Metemoglobinemia", "TCE/hipóxia", "Intoxicação por outros gases"], "es": <String>["CO aislado", "Cianuro aislado", "Metahemoglobinemia", "TCE/hipoxia", "Intoxicación por otros gases"]},
