    doNotDo: {"pt": <String>["Não confiar em SpO₂", "Não usar COHb isolada para gravidade", "Não induzir MetHb desnecessariamente", "Não esquecer cianeto"], "es": <String>["No confiar en SpO₂", "No usar COHb aislada para gravedad", "No inducir MetHb innecesariamente", "No olvidar cianuro"]},
