  ProtocolModel(
id: 'intox_bloqueadores_canal_calcio',
title: {
      'pt': "Intoxicação por Bloqueadores de Canal de Cálcio",
      'es': "Intoxicación por Bloqueadores de Canales de Calcio",
    },
severity: {'pt': "Crítico", 'es': "Crítico"},
    definition: {"pt": "Intoxicação por bloqueadores dos canais de cálcio (CCB) pode produzir choque cardiogênico e/ou vasoplégico, bradicardia, bloqueio AV e hiperglicemia; o fenótipo varia entre verapamil/diltiazem e di-hidropiridínicos como amlodipina.", "es": "Intoxicación por bloqueadores de canales de calcio (CCB) puede producir shock cardiogénico y/o vasopléjico, bradicardia, bloqueo AV e hiperglucemia; el fenotipo varía entre verapamilo/diltiazem y dihidropiridinas como amlodipino."},
    classification: {"pt": "Não di-hidropiridínicos: mais bradicardia, bloqueio AV e depressão miocárdica. Di-hidropiridínicos: vasodilatação predominante, mas overdose maciça perde seletividade e também deprime coração.", "es": "No dihidropiridínicos: más bradicardia, bloqueo AV y depresión miocárdica. Dihidropiridinas: vasodilatación predominante, pero sobredosis masiva pierde selectividad y también deprime corazón."},
    severityCriteria: {"pt": "Hipotensão/choque, bloqueio AV, bradicardia, hiperglicemia, acidose/lactato, edema pulmonar ou necessidade crescente de vasopressor.", "es": "Hipotensión/shock, bloqueo AV, bradicardia, hiperglucemia, acidosis/lactato, edema pulmonar o necesidad creciente de vasopresor."},
    physiopathology: {"pt": "Mecanismo de toxicidade —\nMECANISMO 1 — Bloqueio de canais L de Ca²⁺ no miocárdio → entrada de Ca²⁺ ↓ → inotropismo ↓.\nMECANISMO 2 — Nó SA/AV dependem de corrente de Ca²⁺ → cronotropismo/dromotropismo ↓ → bradicardia/bloqueio.\nMECANISMO 3 — Canais L vasculares bloqueados → vasodilatação → SVR ↓, muito marcada com di-hidropiridínicos.\nMECANISMO 4 — Célula beta pancreática usa entrada de Ca²⁺ para secretar insulina → CCB → insulina ↓ + hiperglicemia.\nMECANISMO 5 — Coração em choque migra para metabolismo de carboidrato; deficiência de insulina reduz uso de glicose → piora energética miocárdica.\nMECANISMO 6 — HIET fornece insulina supraterapêutica → captação/uso de glicose miocárdica ↑ + efeito inotrópico.\nMECANISMO 7 — Cálcio IV aumenta gradiente extracelular e pode melhorar condução/contratilidade, mas raramente basta sozinho.\nDA TOXINA À CONDUTA — CCB → Ca²⁺ cardíaco/vascular/pancreático ↓ → choque + bradi/bloqueio + hiperglicemia → vasopressor + HIET ± cálcio → ECLS se refratário.", "es": "Mecanismo de toxicidad —\nMECANISMO 1 — Bloqueo de canales L de Ca²⁺ miocárdicos → entrada de Ca²⁺ ↓ → inotropismo ↓.\nMECANISMO 2 — Nodo SA/AV dependen de corriente de Ca²⁺ → cronotropismo/dromotropismo ↓ → bradicardia/bloqueo.\nMECANISMO 3 — Canales L vasculares bloqueados → vasodilatación → SVR ↓, muy marcada con dihidropiridinas.\nMECANISMO 4 — Célula beta pancreática usa entrada de Ca²⁺ para secretar insulina → CCB → insulina ↓ + hiperglucemia.\nMECANISMO 5 — Corazón en shock migra a metabolismo de carbohidrato; déficit de insulina reduce uso de glucosa → peor energía miocárdica.\nMECANISMO 6 — HIET aporta insulina supraterapéutica → captación/uso de glucosa miocárdica ↑ + efecto inotrópico.\nMECANISMO 7 — Calcio IV aumenta gradiente extracelular y puede mejorar conducción/contractilidad, pero rara vez basta solo.\nDE LA TOXINA A LA CONDUCTA — CCB → Ca²⁺ cardíaco/vascular/pancreático ↓ → shock + bradi/bloqueo + hiperglucemia → vasopresor + HIET ± calcio → ECLS si refractario."},
    redFlags: {"pt": <String>["Choque", "Bloqueio AV/bradicardia", "Hiperglicemia crescente", "Disfunção ventricular no POCUS", "Amlodipina maciça com vasoplegia refratária"], "es": <String>["Shock", "Bloqueo AV/bradicardia", "Hiperglucemia creciente", "Disfunción ventricular en POCUS", "Amlodipino masivo con vasoplejía refractaria"]},
    differentialDiagnosis: {"pt": <String>["β-bloqueador", "Digoxina", "Clonidina", "IAM/bradiarritmia primária", "Sepse"], "es": <String>["β-bloqueador", "Digoxina", "Clonidina", "IAM/bradiarritmia primaria", "Sepsis"]},
    exams: {"pt": <String>["ECG seriado", "Glicemia frequente", "K/Mg/Ca ionizado", "Gasometria/lactato", "POCUS/eco para fenótipo do choque"], "es": <String>["ECG seriado", "Glucemia frecuente", "K/Mg/Ca ionizado", "Gasometría/lactato", "POCUS/eco para fenotipo del shock"]},
    objectives: {"pt": <String>["Restaurar perfusão cedo", "Iniciar HIET e vasopressor no choque ameaçador à vida", "Definir cardiogênico vs vasoplégico", "Escalar para ECLS sem esperar falência irreversível"], "es": <String>["Restaurar perfusión precoz", "Iniciar HIET y vasopresor en shock potencialmente mortal", "Definir cardiogénico vs vasopléjico", "Escalar a ECLS sin esperar falla irreversible"]},
    drugsFirstLine: {"pt": <String>["HIET: insulina regular 1 U/kg IV de carga, depois 1–10 U/kg/h; fornecer dextrose conforme glicemia e monitorar K", "Norepinefrina/epinefrina conforme fenótipo do choque"], "es": <String>["HIET: insulina regular 1 U/kg IV de carga, luego 1–10 U/kg/h; aportar dextrosa según glucemia y monitorizar K", "Norepinefrina/epinefrina según fenotipo del shock"]},
    drugsSecondLine: {"pt": <String>["Cálcio IV é razoável; usar protocolo institucional/toxicologia com monitorização de Ca ionizado", "Cristaloide cauteloso se responsivo"], "es": <String>["Calcio IV es razonable; usar protocolo institucional/toxicología con monitorización de Ca ionizado", "Cristaloide prudente si responde"]},
    drugsConditional: {"pt": <String>["AHA 2025: glucagon pode ser considerado, mas utilidade é incerta; metileno azul/ILE têm utilidade incerta em choque refratário", "VA-ECMO/ECLS é razoável quando refratário a terapia farmacológica"], "es": <String>["AHA 2025: glucagón puede considerarse, pero su utilidad es incierta; azul de metileno/ILE tienen utilidad incierta en shock refractario", "VA-ECMO/ECLS es razonable cuando es refractario a terapia farmacológica"]},
    drugsContraindicated: {"pt": <String>["Não atrasar HIET esperando cálcio/glucagon resolverem sozinhos", "Não iniciar HIET sem protocolo de glicemia/K", "ILE não é rotina"], "es": <String>["No retrasar HIET esperando que calcio/glucagón resuelvan solos", "No iniciar HIET sin protocolo de glucemia/K", "ILE no es rutina"]},
    scenarios: {"pt": <String>["CASO-BASE — Paciente após verapamil de liberação prolongada: FC 38, PA 68/40, glicose 260 mg/dL.", "EVOLUÇÃO 1 — POCUS mostra baixa contratilidade: vasopressor + HIET são prioridades.", "EVOLUÇÃO 2 — Apesar de doses altas, segue em choque cardiogênico: acionar ECLS cedo; formulação prolongada exige vigilância de deterioração tardia."], "es": <String>["CASO-BASE — Paciente tras verapamilo de liberación prolongada: FC 38, PA 68/40, glucosa 260 mg/dL.", "EVOLUCIÓN 1 — POCUS muestra baja contractilidad: vasopresor + HIET son prioridades.", "EVOLUCIÓN 2 — Pese a dosis altas, persiste shock cardiogénico: activar ECLS precozmente; liberación prolongada exige vigilancia tardía."]},
    monitoring: {"pt": <String>["PA/perfusão/diurese", "ECG", "Glicemia inicialmente a cada 15–30 min no HIET", "K seriado", "POCUS/lactato"], "es": <String>["PA/perfusión/diuresis", "ECG", "Glucemia inicialmente cada 15–30 min con HIET", "K seriado", "POCUS/lactato"]},
