    redFlags: {"pt": <String>["Confusão/ataxia importante", "Convulsão", "Arritmia", "DRC/AKI", "Li elevado com queda lenta"], "es": <String>["Confusión/ataxia importante", "Convulsión", "Arritmia", "ERC/AKI", "Li elevado con descenso lento"]},
