    differentialDiagnosis: {"pt": <String>["Celulite", "Pioderma gangrenoso", "Herpes-zóster", "Vasculite", "Queimadura"], "es": <String>["Celulitis", "Pioderma gangrenoso", "Herpes zóster", "Vasculitis", "Quemadura"]},
