  ProtocolModel(
    id: 'endocr_crise_hipercalcemica',
    title: {"pt": "Crise Hipercalcêmica Grave", "es": "Crisis Hipercalcémica Grave"},
    severity: {"pt": "Crítico — Emergência Metabólica", "es": "Crítico — Emergencia Metabólica"},
    definition: {"pt": "Hipercalcemia grave, geralmente Ca sérico >14 mg/dL ou hipercalcemia sintomática com disfunção neurológica, renal, cardíaca ou gastrointestinal.", "es": "Hipercalcemia grave, habitualmente Ca sérico >14 mg/dL o hipercalcemia sintomática con disfunción neurológica, renal, cardíaca o gastrointestinal."},
    physiopathology: {"pt": "O excesso de cálcio reduz excitabilidade neuromuscular, causa diurese nefrogênica e desidratação, encurta QT e pode produzir lesão renal. Malignidade e hiperparatireoidismo estão entre as causas principais.", "es": "El exceso de calcio reduce excitabilidad neuromuscular, causa diuresis nefrogénica y deshidratación, acorta QT y puede producir lesión renal. Malignidad e hiperparatiroidismo son causas principales."},
    recognize: {"pt": "Desidratação, poliúria, náuseas, constipação, fraqueza, confusão, sonolência, arritmia ou IRA em paciente com cálcio total corrigido/ionizado elevado.", "es": "Deshidratación, poliuria, náuseas, estreñimiento, debilidad, confusión, somnolencia, arritmia o LRA con calcio corregido/ionizado elevado."},
    redFlags: {"pt": ["Ca >14 mg/dL", "Alteração do sensório", "Arritmia", "IRA/oligúria", "Desidratação/choque"], "es": ["Ca >14 mg/dL", "Alteración del sensorio", "Arritmia", "LRA/oliguria", "Deshidratación/shock"]},
    differentialDiagnosis: {"pt": ["Malignidade", "Hiperparatireoidismo", "Intoxicação por vitamina D", "Granulomatoses", "Fármacos como tiazídicos/lítio"], "es": ["Malignidad", "Hiperparatiroidismo", "Intoxicación por vitamina D", "Granulomatosis", "Fármacos como tiazidas/litio"]},
    exams: {"pt": ["Cálcio total + albumina ou cálcio ionizado", "Creatinina, Mg, P, K", "PTH como primeiro discriminador etiológico", "PTHrP, 25-OH-D e 1,25-OH2-D conforme contexto", "ECG"], "es": ["Calcio total + albúmina o calcio ionizado", "Creatinina, Mg, P, K", "PTH como primer discriminador etiológico", "PTHrP, 25-OH-D y 1,25-OH2-D según contexto", "ECG"]},
    objectives: {"pt": ["Restaurar volemia", "Reduzir cálcio rapidamente", "Bloquear reabsorção óssea", "Tratar etiologia"], "es": ["Restaurar volemia", "Reducir calcio rápidamente", "Bloquear resorción ósea", "Tratar etiología"]},
    actions: {"pt": ["1. Suspender cálcio/vitamina D e fármacos contribuintes quando possível", "2. Solução salina isotônica IV guiada por volemia, função renal e cardíaca", "3. Em hipercalcemia grave de malignidade, associar calcitonina a bisfosfonato IV ou denosumabe para queda rápida + efeito sustentado", "4. Calcitonina 4 UI/kg SC/IM 12/12h; limitar geralmente a 48–72 h por taquifilaxia", "5. Antirreabsortivo: zoledronato IV ou denosumabe conforme etiologia, função renal, disponibilidade e guideline; Endocrine Society sugere denosumabe sobre bisfosfonato na HCM", "6. Hipercalcemia mediada por calcitriol: glicocorticoide é tratamento etiológico inicial", "7. Hemodiálise se grave/refratária com insuficiência renal, sobrecarga ou impossibilidade de hidratação"], "es": ["1. Suspender calcio/vitamina D y fármacos contribuyentes cuando sea posible", "2. Solución salina isotónica IV guiada por volemia, función renal y cardíaca", "3. En hipercalcemia grave por malignidad, asociar calcitonina a bisfosfonato IV o denosumab para caída rápida + efecto sostenido", "4. Calcitonina 4 UI/kg SC/IM c/12 h; limitar generalmente a 48–72 h por taquifilaxia", "5. Antirresortivo: zoledronato IV o denosumab según etiología, función renal, disponibilidad y guideline; Endocrine Society sugiere denosumab sobre bisfosfonato en HCM", "6. Hipercalcemia mediada por calcitriol: glucocorticoide como tratamiento etiológico inicial", "7. Hemodiálisis si grave/refractaria con insuficiencia renal, sobrecarga o imposibilidad de hidratar"]},
    drugsFirstLine: {"pt": ["Cristaloide isotônico", "Calcitonina em hipercalcemia grave", "Bisfosfonato IV ou denosumabe conforme etiologia"], "es": ["Cristaloide isotónico", "Calcitonina en hipercalcemia grave", "Bisfosfonato IV o denosumab según etiología"]},
    drugsConditional: {"pt": ["Glicocorticoide em hipercalcemia mediada por calcitriol"], "es": ["Glucocorticoide en hipercalcemia mediada por calcitriol"]},
    drugsContraindicated: {"pt": ["Diurético de alça de rotina antes de corrigir volemia"], "es": ["Diurético de asa rutinario antes de corregir volemia"]},
    monitoring: {"pt": ["Cálcio seriado", "Diurese/creatinina", "Mg/P/K", "ECG e volemia"], "es": ["Calcio seriado", "Diuresis/creatinina", "Mg/P/K", "ECG y volemia"]},
    complications: {"pt": ["Arritmias", "IRA", "Coma", "Pancreatite", "Óbito"], "es": ["Arritmias", "LRA", "Coma", "Pancreatitis", "Muerte"]},
    doNotDo: {"pt": ["NÃO usar furosemida rotineiramente para 'lavar cálcio' antes de euvolemia", "NÃO prolongar calcitonina além de 48–72 h esperando efeito sustentado", "NÃO esquecer PTH para direcionar etiologia"], "es": ["NO usar furosemida rutinariamente para 'lavar calcio' antes de euvolemia", "NO prolongar calcitonina más de 48–72 h esperando efecto sostenido", "NO olvidar PTH para dirigir etiología"]},
    pearls: {"pt": ["Endocrine Society recomenda antirreabsortivo em todos os adultos com hipercalcemia da malignidade", "Calcitonina atua rápido, mas perde efeito por taquifilaxia"], "es": ["Endocrine Society recomienda antirresortivo en adultos con hipercalcemia de malignidad", "La calcitonina actúa rápido, pero pierde efecto por taquifilaxia"]},
