    redFlags: {"pt": ["Instabilidade hemodinâmica", "Hemoglobina em queda", "Aspiração/comprometimento de via aérea", "Sangramento persistente apesar de tamponamento"], "es": ["Inestabilidad hemodinámica", "Hemoglobina en descenso", "Aspiración/compromiso de vía aérea", "Sangrado persistente pese a taponamiento"]},
    differentialDiagnosis: {"pt": ["Epistaxe anterior", "Tumor sinonasal", "Trauma", "Coagulopatia"], "es": ["Epistaxis anterior", "Tumor sinonasal", "Trauma", "Coagulopatía"]},
