  ProtocolModel(
    id: 'infect_endocardite_infecciosa_aguda',
    title: {"pt": "Endocardite Infecciosa Aguda", "es": "Endocarditis Infecciosa Aguda"},
    severity: {"pt": "Crítico", "es": "Crítico"},
    definition: {"pt": "Infecção do endocárdio/valvas ou material intracardíaco, capaz de causar insuficiência valvar aguda, abscessos, embolização séptica e sepse.", "es": "Infección del endocardio/válvulas o material intracardíaco, capaz de causar insuficiencia valvular aguda, abscesos, embolización séptica y sepsis."},
    physiopathology: {"pt": "Bacteremia adere a endocárdio lesionado ou material protético, formando vegetações; destruição local e embolização podem produzir falência cardíaca e complicações sistêmicas.", "es": "La bacteriemia se adhiere a endocardio lesionado o material protésico formando vegetaciones; destrucción local y embolización pueden causar falla cardíaca y complicaciones sistémicas."},
    recognize: {"pt": "Febre/sepsis + sopro novo, prótese/dispositivo, uso de drogas IV, bacteremia persistente, fenômenos embólicos ou imunológicos.", "es": "Fiebre/sepsis + soplo nuevo, prótesis/dispositivo, drogas IV, bacteriemia persistente, fenómenos embólicos o inmunológicos."},
    redFlags: {"pt": ["Edema pulmonar/choque por insuficiência valvar", "Bloqueio AV novo sugerindo abscesso", "Embolização cerebral/visceral", "Bacteremia persistente", "Vegetação grande com eventos embólicos"], "es": ["Edema pulmonar/shock por insuficiencia valvular", "Bloqueo AV nuevo sugiriendo absceso", "Embolización cerebral/visceral", "Bacteriemia persistente", "Vegetación grande con eventos embólicos"]},
    differentialDiagnosis: {"pt": ["Sepse sem foco", "Miocardite", "Trombose valvar", "Endocardite não infecciosa", "Vasculite"], "es": ["Sepsis sin foco", "Miocarditis", "Trombosis valvular", "Endocarditis no infecciosa", "Vasculitis"]},
    exams: {"pt": ["Três conjuntos de hemoculturas de sítios distintos antes do antibiótico quando isso não atrasa terapia em paciente instável", "TTE inicial; TEE se prótese/dispositivo, TTE negativo com alta suspeita ou avaliação de complicação", "Hemograma, renal/hepática, PCR/VHS", "ECG para bloqueios", "TC/RM/PET conforme complicações e material protético"], "es": ["Tres juegos de hemocultivos de sitios distintos antes del antibiótico cuando no retrasa terapia en inestable", "ETT inicial; ETE si prótesis/dispositivo, ETT negativo con alta sospecha o evaluación de complicación", "Hemograma, renal/hepática, PCR/VSG", "ECG para bloqueos", "TC/RM/PET según complicaciones y material protésico"]},
    objectives: {"pt": ["Obter diagnóstico microbiológico", "Iniciar antibiótico IV apropriado", "Detectar indicação cirúrgica precoce", "Prevenir/gerenciar embolização e falência cardíaca"], "es": ["Obtener diagnóstico microbiológico", "Iniciar antibiótico IV apropiado", "Detectar indicación quirúrgica precoz", "Prevenir/manejar embolización y falla cardíaca"]},
    actions: {"pt": ["1. Acionar Endocarditis Team/cardiologia-infectologia/cirurgia cardíaca em caso provável/complicado", "2. Obter 3 pares/conjuntos de hemoculturas antes do antibiótico se clinicamente possível", "3. Em choque/sepsis, colher culturas rapidamente e iniciar antibiótico IV empírico sem atraso indevido", "4. Regime empírico depende de valva nativa vs prótese, aquisição comunitária vs hospitalar e resistência local; deve cobrir estafilococos, estreptococos e enterococos conforme cenário, seguindo protocolo institucional/ESC", "5. Ajustar terapia imediatamente à identificação/sensibilidade", "6. Fazer TTE e complementar com TEE quando indicado", "7. Avaliar diariamente cirurgia: três grandes razões ESC são insuficiência cardíaca, infecção não controlada e prevenção de embolização séptica", "8. Remover material/dispositivo infectado quando indicado", "9. Avaliar focos metastáticos e complicações neurológicas antes de decisões antitrombóticas/cirúrgicas"], "es": ["1. Activar Endocarditis Team/cardiología-infectología/cirugía cardíaca en caso probable/complicado", "2. Obtener 3 pares/juegos de hemocultivos antes del antibiótico si es clínicamente posible", "3. En shock/sepsis, tomar cultivos rápidamente e iniciar antibiótico IV empírico sin demora indebida", "4. Régimen empírico depende de válvula nativa vs prótesis, adquisición comunitaria vs hospitalaria y resistencia local; debe cubrir estafilococos, estreptococos y enterococos según escenario, siguiendo protocolo institucional/ESC", "5. Ajustar terapia inmediatamente a identificación/sensibilidad", "6. Realizar ETT y complementar con ETE cuando corresponda", "7. Evaluar cirugía diariamente: tres grandes razones ESC son insuficiencia cardíaca, infección no controlada y prevención de embolización séptica", "8. Retirar material/dispositivo infectado cuando esté indicado", "9. Evaluar focos metastásicos y complicaciones neurológicas antes de decisiones antitrombóticas/quirúrgicas"]},
    drugsFirstLine: {"pt": ["Antibiótico IV empírico orientado ao cenário e resistência local, seguido de terapia dirigida por cultura"], "es": ["Antibiótico IV empírico orientado al escenario y resistencia local, seguido de terapia dirigida por cultivo"]},
    drugsContraindicated: {"pt": ["Aminoglicosídeo de rotina em endocardite estafilocócica de valva nativa — ESC não recomenda", "Rifampicina precoce em valva nativa sem material protético"], "es": ["Aminoglucósido rutinario en endocarditis estafilocócica de válvula nativa — ESC no recomienda", "Rifampicina precoz en válvula nativa sin material protésico"]},
    monitoring: {"pt": ["Hemoculturas até negativação", "Função renal/hepática e toxicidade antibiótica", "ECG", "Eco seriado se complicação", "Sinais neurológicos/embólicos"], "es": ["Hemocultivos hasta negativización", "Función renal/hepática y toxicidad antibiótica", "ECG", "Eco seriado si complicación", "Signos neurológicos/embólicos"]},
    complications: {"pt": ["Insuficiência cardíaca aguda", "Abscesso/perfuração", "AVC/êmbolos", "Bloqueio AV", "Sepse/choque"], "es": ["Insuficiencia cardíaca aguda", "Absceso/perforación", "ACV/émbolos", "Bloqueo AV", "Sepsis/shock"]},
    doNotDo: {"pt": ["NÃO atrasar hemoculturas/antibiótico em choque", "NÃO confiar em TTE negativo com alta suspeita", "NÃO esquecer avaliação cirúrgica precoce", "NÃO anticoagular apenas por presença de vegetação"], "es": ["NO retrasar hemocultivos/antibiótico en shock", "NO confiar en ETT negativo con alta sospecha", "NO olvidar evaluación quirúrgica precoz", "NO anticoagular solo por presencia de vegetación"]},
    pearls: {"pt": ["ESC 2023 inclui novo algoritmo diagnóstico e Endocarditis Team; corrigendum em janeiro de 2025", "As três razões centrais para cirurgia são IC, infecção não controlada e prevenção de embolização"], "es": ["ESC 2023 incluye nuevo algoritmo diagnóstico y Endocarditis Team; corrigendum en enero de 2025", "Las tres razones centrales para cirugía son IC, infección no controlada y prevención de embolización"]},
    references: {"pt": ["https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/endocarditis/", "https://www.escardio.org/guidelines/clinical-practice-guidelines/pocket-guidelines/infective-endocarditis/"], "es": ["https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/endocarditis/", "https://www.escardio.org/guidelines/clinical-practice-guidelines/pocket-guidelines/infective-endocarditis/"]},
    avoid: {"pt": "Evitar antibiótico empírico genérico sem considerar tipo de valva, aquisição e resistência local.", "es": "Evitar antibiótico empírico genérico sin considerar tipo de válvula, adquisición y resistencia local."},
