  ProtocolModel(
    id: 'neuro_miastenia_crise',
    title: {"pt": "Crise Miastênica", "es": "Crisis Miasténica"},
    severity: {"pt": "Crítico — Emergência Neuromuscular", "es": "Crítico — Emergencia Neuromuscular"},
    definition: {"pt": "Piora rápida da miastenia gravis com fraqueza respiratória e/ou bulbar ameaçando ou causando insuficiência ventilatória, frequentemente exigindo ventilação não invasiva ou intubação.", "es": "Empeoramiento rápido de miastenia gravis con debilidad respiratoria y/o bulbar que amenaza o causa insuficiencia ventilatoria, frecuentemente requiriendo ventilación no invasiva o intubación."},
    physiopathology: {"pt": "Falha da transmissão neuromuscular reduz força diafragmática, intercostal e bulbar; infecção, cirurgia, gestação e fármacos podem precipitar deterioração.", "es": "Falla de transmisión neuromuscular reduce fuerza diafragmática, intercostal y bulbar; infección, cirugía, embarazo y fármacos pueden precipitar deterioro."},
    recognize: {"pt": "Dispneia, ortopneia, voz hipofônica/nasal, disfagia, tosse fraca, secreções, uso de musculatura acessória e queda progressiva de capacidade vital.", "es": "Disnea, ortopnea, voz hipofónica/nasal, disfagia, tos débil, secreciones, uso de musculatura accesoria y caída progresiva de capacidad vital."},
    redFlags: {"pt": ["Fraqueza bulbar com aspiração", "Hipercapnia", "Incapacidade de contar/falar frases", "Tosse ineficaz", "Deterioração rápida"], "es": ["Debilidad bulbar con aspiración", "Hipercapnia", "Incapacidad para contar/hablar frases", "Tos ineficaz", "Deterioro rápido"]},
    differentialDiagnosis: {"pt": ["Síndrome de Guillain-Barré", "Botulismo", "Crise colinérgica rara", "Pneumonia/TEP", "Lambert-Eaton"], "es": ["Síndrome de Guillain-Barré", "Botulismo", "Crisis colinérgica rara", "Neumonía/TEP", "Lambert-Eaton"]},
    exams: {"pt": ["Capacidade vital forçada e força inspiratória seriadas, interpretadas com clínica", "Gasometria se fadiga/hipoventilação", "Rx/TC conforme precipitante", "Eletrólitos, Mg e investigação de infecção"], "es": ["Capacidad vital forzada y fuerza inspiratoria seriadas, interpretadas con clínica", "Gasometría si fatiga/hipoventilación", "Rx/TC según precipitante", "Electrolitos, Mg e investigación de infección"]},
    objectives: {"pt": ["Antecipar falência respiratória", "Proteger via aérea", "Iniciar PLEX ou IVIG", "Tratar precipitante e evitar fármacos agravantes"], "es": ["Anticipar falla respiratoria", "Proteger vía aérea", "Iniciar PLEX o IVIG", "Tratar precipitante y evitar fármacos agravantes"]},
    actions: {"pt": ["1. Admitir em UTI/unidade monitorizada com experiência neuromuscular", "2. Avaliar repetidamente função bulbar, tosse e parâmetros respiratórios; não usar um único valor de FVC/NIF isoladamente para decidir via aérea", "3. Intubar precocemente se fadiga progressiva, secreções/aspiração, hipercapnia ou falência ventilatória", "4. IVIG ou plasmaférese são terapias de curto prazo de primeira linha; consenso sugere PLEX com início mais rápido, mas escolha depende de comorbidades e disponibilidade", "5. IVIG costuma totalizar 2 g/kg divididos em 2–5 dias; PLEX frequentemente é realizado em série de trocas conforme protocolo", "6. Corticoide/imunossupressão sustentada pode ser iniciada, lembrando que corticoide pode piorar transitoriamente a fraqueza; timing deve ser individualizado", "7. Após intubação, piridostigmina costuma ser temporariamente reduzida/suspensa para diminuir secreções e reiniciada na recuperação conforme equipe especializada", "8. Tratar precipitante, especialmente infecção", "9. Evitar ou usar com grande cautela fármacos que pioram transmissão neuromuscular, como magnésio IV, aminoglicosídeos, fluoroquinolonas e alguns macrolídeos/betabloqueadores"], "es": ["1. Ingresar en UCI/unidad monitorizada con experiencia neuromuscular", "2. Reevaluar función bulbar, tos y parámetros respiratorios; no usar un único FVC/NIF aislado para decidir vía aérea", "3. Intubar precozmente si fatiga progresiva, secreciones/aspiración, hipercapnia o falla ventilatoria", "4. IVIG o plasmaféresis son terapias cortas de primera línea; consenso sugiere PLEX con inicio más rápido, pero elección depende de comorbilidades y disponibilidad", "5. IVIG suele totalizar 2 g/kg dividido en 2–5 días; PLEX suele realizarse en serie de intercambios según protocolo", "6. Corticoide/inmunosupresión sostenida puede iniciarse recordando que corticoide puede empeorar transitoriamente la debilidad; timing individualizado", "7. Tras intubación, piridostigmina suele reducirse/suspenderse temporalmente para disminuir secreciones y reiniciarse durante recuperación según equipo especializado", "8. Tratar precipitante, especialmente infección", "9. Evitar o usar con gran cautela fármacos que empeoran transmisión neuromuscular como magnesio IV, aminoglucósidos, fluoroquinolonas y algunos macrólidos/betabloqueantes"]},
    drugsFirstLine: {"pt": ["IVIG 2 g/kg total em 2–5 dias OU plasmaférese conforme protocolo"], "es": ["IVIG 2 g/kg total en 2–5 días O plasmaféresis según protocolo"]},
    drugsConditional: {"pt": ["Corticosteroide/imunossupressão sustentada com timing individualizado"], "es": ["Corticoide/inmunosupresión sostenida con timing individualizado"]},
    drugsContraindicated: {"pt": ["Magnésio IV salvo indicação vital e monitorização especializada", "Fármacos conhecidos por piorar MG devem ser evitados quando há alternativas"], "es": ["Magnesio IV salvo indicación vital y monitorización especializada", "Fármacos conocidos por empeorar MG deben evitarse si hay alternativas"]},
    monitoring: {"pt": ["FVC/NIF seriados + clínica", "Gasometria", "Tosse/deglutição/secreções", "ECG/oximetria"], "es": ["FVC/NIF seriados + clínica", "Gasometría", "Tos/deglución/secreciones", "ECG/oximetría"]},
    complications: {"pt": ["Insuficiência respiratória", "Aspiração/pneumonia", "Complicações de ventilação", "Trombose/IRA com IVIG ou acesso de PLEX"], "es": ["Insuficiencia respiratoria", "Aspiración/neumonía", "Complicaciones de ventilación", "Trombosis/LRA con IVIG o acceso de PLEX"]},
    doNotDo: {"pt": ["NÃO esperar hipoxemia tardia para reconhecer falência ventilatória", "NÃO usar apenas um cutoff de FVC para decidir intubação", "NÃO administrar magnésio rotineiramente", "NÃO ignorar fraqueza bulbar"], "es": ["NO esperar hipoxemia tardía para reconocer falla ventilatoria", "NO usar solo un cutoff de FVC para decidir intubación", "NO administrar magnesio rutinariamente", "NO ignorar debilidad bulbar"]},
    pearls: {"pt": ["Consenso internacional mantém IVIG e PLEX como pilares da crise", "Guideline europeu recente reforça admissão rápida em UTI e IVIG ou PE/IA", "PLEX tende a agir mais rápido segundo consenso de especialistas"], "es": ["Consenso internacional mantiene IVIG y PLEX como pilares de la crisis", "Guideline europeo reciente refuerza ingreso rápido en UCI e IVIG o PE/IA", "PLEX tiende a actuar más rápido según consenso experto"]},
    references: {"pt": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC7884987/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC4977114/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC10752078/"], "es": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC7884987/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC4977114/", "https://pmc.ncbi.nlm.nih.gov/articles/PMC10752078/"]},
    avoid: {"pt": "Evitar atraso de via aérea e exposição a medicamentos que pioram a transmissão neuromuscular.", "es": "Evitar retraso de vía aérea y exposición a fármacos que empeoran transmisión neuromuscular."},
    drugs: [],
  ),

  // MEDCASES_SIMULACOES_200TH_UMBILICAL_CORD_PROLAPSE_2026_V1_B_R0
  ProtocolModel(
    id: 'obstetr_prolapso_cordao_umbilical',
    title: {"pt": "Prolapso de Cordão Umbilical — Emergência Intraparto", "es": "Prolapso de Cordón Umbilical — Emergencia Intraparto"},
    severity: {"pt": "Crítico — Emergência Obstétrica", "es": "Crítico — Emergencia Obstétrica"},
    definition: {"pt": "Descida do cordão umbilical através do colo ao lado da apresentação fetal (oculto) ou além dela (prolapso evidente) após rotura das membranas. A compressão do cordão pode interromper rapidamente o fluxo fetal e causar hipóxia grave.", "es": "Descenso del cordón umbilical a través del cuello junto a la presentación fetal (oculto) o por delante de ella (prolapso manifiesto) tras la rotura de membranas. La compresión puede interrumpir rápidamente el flujo fetal y causar hipoxia grave."},
    physiopathology: {"pt": "A apresentação fetal comprime o cordão prolapsado contra o colo, pelve ou canal de parto. A compressão venosa e arterial e o vasoespasmo do cordão reduzem a perfusão fetoplacentária, produzindo desaceleração prolongada, bradicardia, acidose e potencial encefalopatia hipóxico-isquêmica.", "es": "La presentación fetal comprime el cordón prolapsado contra cuello, pelvis o canal del parto. La compresión venosa y arterial y el vasoespasmo reducen la perfusión fetoplacentaria, causando desaceleración prolongada, bradicardia, acidosis y potencial encefalopatía hipóxico-isquémica."},
    recognize: {"pt": "Bradicardia fetal ou desaceleração prolongada súbita imediatamente após rotura espontânea/artificial de membranas, especialmente com apresentação alta, pélvica, transversa, prematuridade ou polidrâmnio. O cordão pode ser palpável ao toque vaginal ou visível na vagina/vulva.", "es": "Bradicardia fetal o desaceleración prolongada súbita inmediatamente tras rotura espontánea/artificial de membranas, especialmente con presentación alta, podálica, transversa, prematuridad o polihidramnios. El cordón puede palparse al tacto vaginal o verse en vagina/vulva."},
    redFlags: {"pt": ["Bradicardia fetal persistente", "Traçado fetal patológico após rotura de membranas", "Cordão visível ou palpável à frente da apresentação", "Apresentação fetal alta/não encaixada após amniotomia", "Demora prevista para parto definitivo"], "es": ["Bradicardia fetal persistente", "Registro fetal patológico tras rotura de membranas", "Cordón visible o palpable por delante de la presentación", "Presentación fetal alta/no encajada tras amniotomía", "Demora prevista para parto definitivo"]},
    differentialDiagnosis: {"pt": ["Descolamento prematuro de placenta", "Rotura uterina", "Hipotensão materna pós-neuroeixo", "Taquissistolia uterina", "Vasa prévia rota"], "es": ["Desprendimiento prematuro de placenta", "Rotura uterina", "Hipotensión materna posneuroaxial", "Taquisistolia uterina", "Vasa previa rota"]},
    exams: {"pt": ["Diagnóstico é clínico — não atrasar parto para exames", "Cardiotocografia contínua enquanto se prepara o parto, se isso não atrasar a intervenção", "Após o nascimento: gasometria de cordão pareada quando disponível e avaliação neonatal"], "es": ["Diagnóstico clínico — no retrasar el parto por estudios", "Cardiotocografía continua mientras se prepara el parto si no retrasa la intervención", "Tras el nacimiento: gases de cordón pareados cuando estén disponibles y evaluación neonatal"]},
    objectives: {"pt": ["Reduzir imediatamente a compressão do cordão", "Manter perfusão fetal enquanto se organiza o parto", "Realizar o nascimento pela via mais rápida e segura", "Evitar manipulação excessiva do cordão e vasoespasmo"], "es": ["Reducir inmediatamente la compresión del cordón", "Mantener perfusión fetal mientras se organiza el parto", "Realizar el nacimiento por la vía más rápida y segura", "Evitar manipulación excesiva del cordón y vasoespasmo"]},
    actions: {"pt": ["1. Declarar PROLAPSO DE CORDÃO e chamar imediatamente obstetra sênior, anestesia, equipe de centro cirúrgico e neonatologia", "2. Aliviar a compressão elevando manualmente a apresentação fetal com dois dedos/mão vaginal; manter pressão suficiente para afastar a apresentação do cordão", "3. Posicionar em joelho-peito ou decúbito lateral esquerdo com cabeça baixa; durante transporte, posição lateral exagerada é mais segura que joelho-peito", "4. Manipular o mínimo possível alças de cordão exteriorizadas para reduzir vasoespasmo; não tentar reposicionar o cordão acima da apresentação para continuar o trabalho de parto", "5. Se o intervalo até o parto provavelmente será prolongado, considerar enchimento vesical com aproximadamente 500–750 mL de solução através de Foley para manter a apresentação elevada; esvaziar a bexiga imediatamente antes do parto", "6. Se persistirem alterações da frequência fetal após descompressão mecânica e houver atraso inevitável, pode-se considerar tocolítico de curta ação, por exemplo terbutalina 0,25 mg SC, sem atrasar o parto", "7. Se parto vaginal não é iminente, cesárea é a via recomendada. Com FCF suspeita/patológica, realizar cesárea categoria 1 visando nascimento em até 30 minutos ou menos, sem comprometer segurança materna", "8. Se colo completamente dilatado e nascimento vaginal operatório for claramente mais rápido e seguro, pode ser realizado por operador experiente", "9. Manter elevação da apresentação até o momento em que a equipe cirúrgica assuma e a descompressão possa ser liberada de forma segura", "10. Neonatologista/profissional competente em reanimação deve estar presente; coletar gasometria de cordão pareada quando possível"], "es": ["1. Declarar PROLAPSO DE CORDÓN y llamar inmediatamente obstetra senior, anestesia, quirófano y neonatología", "2. Aliviar compresión elevando manualmente la presentación fetal con dos dedos/mano vaginal; mantener presión suficiente para separarla del cordón", "3. Posicionar en rodillas-pecho o decúbito lateral izquierdo con cabeza baja; durante traslado, posición lateral exagerada es más segura que rodillas-pecho", "4. Manipular lo mínimo posible las asas de cordón exteriorizadas para reducir vasoespasmo; no intentar reponer el cordón por encima de la presentación para continuar el trabajo de parto", "5. Si el intervalo hasta el parto probablemente será prolongado, considerar llenado vesical con aproximadamente 500–750 mL mediante Foley para mantener elevada la presentación; vaciar vejiga inmediatamente antes del parto", "6. Si persisten alteraciones de la frecuencia fetal tras descompresión mecánica y habrá demora inevitable, puede considerarse tocolítico de acción corta, por ejemplo terbutalina 0,25 mg SC, sin retrasar el parto", "7. Si el parto vaginal no es inminente, la cesárea es la vía recomendada. Con FCF sospechosa/patológica, realizar cesárea categoría 1 buscando nacimiento en 30 minutos o menos, sin comprometer seguridad materna", "8. Si cuello completamente dilatado y parto vaginal instrumental es claramente más rápido y seguro, puede realizarse por operador experto", "9. Mantener elevación de la presentación hasta que el equipo quirúrgico asuma y pueda liberarse la descompresión de forma segura", "10. Debe estar presente personal competente en reanimación neonatal; obtener gases de cordón pareados cuando sea posible"]},
    drugsFirstLine: {"pt": [], "es": []},
    drugsConditional: {"pt": ["Terbutalina 0,25 mg SC pode ser considerada quando persistem alterações fetais após descompressão mecânica e o parto sofrerá atraso; nunca deve atrasar o nascimento"], "es": ["Terbutalina 0,25 mg SC puede considerarse si persisten alteraciones fetales tras descompresión mecánica y el parto se demorará; nunca debe retrasar el nacimiento"]},
    drugsContraindicated: {"pt": ["Tocolítico como substituto do parto definitivo", "Medicação ou sedação que atrase a transferência para o centro cirúrgico"], "es": ["Tocolítico como sustituto del parto definitivo", "Medicación o sedación que retrase traslado a quirófano"]},
    monitoring: {"pt": ["FCF contínua quando possível", "Tempo diagnóstico-decisão-parto", "Sinais vitais maternos", "Resposta fetal às manobras de descompressão"], "es": ["FCF continua cuando sea posible", "Tiempo diagnóstico-decisión-parto", "Signos vitales maternos", "Respuesta fetal a maniobras de descompresión"]},
    complications: {"pt": ["Hipóxia e acidose fetal", "Encefalopatia hipóxico-isquêmica", "Paralisia cerebral", "Óbito perinatal", "Complicações de cesárea emergencial"], "es": ["Hipoxia y acidosis fetal", "Encefalopatía hipóxico-isquémica", "Parálisis cerebral", "Muerte perinatal", "Complicaciones de cesárea emergente"]},
    doNotDo: {"pt": ["NÃO empurrar o cordão de volta para dentro do útero com intenção de continuar o trabalho de parto", "NÃO manipular excessivamente o cordão exteriorizado", "NÃO perder tempo com exames de imagem", "NÃO interromper a elevação da apresentação antes que a compressão esteja definitivamente resolvida", "NÃO usar tocolítico para postergar o parto"], "es": ["NO empujar el cordón nuevamente al útero con intención de continuar el trabajo de parto", "NO manipular excesivamente el cordón exteriorizado", "NO perder tiempo con estudios de imagen", "NO interrumpir la elevación de la presentación antes de resolver definitivamente la compresión", "NO usar tocolítico para postergar el parto"]},
    pearls: {"pt": ["RCOG Green-top 50 foi revisado em dezembro de 2024 e teve validade estendida por 2 anos", "A primeira ação não é a cesárea em si: é aliviar imediatamente a compressão enquanto a equipe organiza o parto", "Cesárea categoria 1 visa nascimento em ≤30 minutos quando há traçado fetal suspeito/patológico, sem comprometer a segurança materna", "A informação pública do RCOG sobre prolapso de cordão foi atualizada em agosto de 2025"], "es": ["RCOG Green-top 50 fue revisada en diciembre de 2024 y su vigencia se extendió 2 años", "La primera acción no es la cesárea en sí: es aliviar inmediatamente la compresión mientras se organiza el parto", "Cesárea categoría 1 busca nacimiento en ≤30 minutos cuando hay registro fetal sospechoso/patológico, sin comprometer seguridad materna", "La información pública de RCOG sobre prolapso de cordón fue actualizada en agosto de 2025"]},
    references: {"pt": ["https://www.rcog.org.uk/guidance/browse-all-guidance/green-top-guidelines/umbilical-cord-prolapse-green-top-guideline-no-50/", "https://www.rcog.org.uk/for-the-public/browse-our-patient-information/umbilical-cord-prolapse-in-late-pregnancy/", "https://www.rcog.org.uk/media/3wykswng/gtg-50-umbilicalcordprolapse-2014.pdf"], "es": ["https://www.rcog.org.uk/guidance/browse-all-guidance/green-top-guidelines/umbilical-cord-prolapse-green-top-guideline-no-50/", "https://www.rcog.org.uk/for-the-public/browse-our-patient-information/umbilical-cord-prolapse-in-late-pregnancy/", "https://www.rcog.org.uk/media/3wykswng/gtg-50-umbilicalcordprolapse-2014.pdf"]},
    avoid: {"pt": "Evitar qualquer manobra ou investigação que prolongue a compressão do cordão ou atrase o nascimento definitivo.", "es": "Evitar cualquier maniobra o estudio que prolongue la compresión del cordón o retrase el nacimiento definitivo."},
    drugs: [],
  ),

