    drugsContraindicated: {"pt": ["Corticosteroide como tratamento específico"], "es": ["Corticoide como tratamiento específico"]},
    monitoring: {"pt": ["FVC e tosse", "Saturação/gasometria", "ECG/PA", "Força bulbar e motora"], "es": ["FVC y tos", "Saturación/gasometría", "ECG/PA", "Fuerza bulbar y motora"]},
    complications: {"pt": ["Falência respiratória", "Aspiração", "Arritmias", "TVP/TEP", "Fraqueza residual"], "es": ["Falla respiratoria", "Aspiración", "Arritmias", "TVP/TEP", "Debilidad residual"]},
    doNotDo: {"pt": ["NÃO usar corticosteroide para tratar GBS", "NÃO esperar dessaturação para reconhecer hipoventilação", "NÃO confiar em uma única FVC"], "es": ["NO usar corticoides para tratar GBS", "NO esperar desaturación para reconocer hipoventilación", "NO confiar en una sola FVC"]},
    pearls: {"pt": ["EAN/PNS 2023 recomenda IVIG ou plasmaférese e desaconselha corticosteroides", "Fraqueza bulbar/tosse ineficaz elevam risco respiratório"], "es": ["EAN/PNS 2023 recomienda IVIG o plasmaféresis y desaconseja corticoides", "Debilidad bulbar/tos ineficaz elevan riesgo respiratorio"]},
