  ProtocolModel(
    id: 'neuro_hemorragia_subaracnoidea_aneurismatica',
    title: {"pt": "Hemorragia Subaracnóidea Aneurismática", "es": "Hemorragia Subaracnoidea Aneurismática"},
    severity: {"pt": "Crítico — Emergência Neurovascular", "es": "Crítico — Emergencia Neurovascular"},
    definition: {"pt": "Sangramento subaracnóideo por ruptura aneurismática, com risco de ressangramento, hidrocefalia e isquemia cerebral tardia.", "es": "Sangrado subaracnoideo por rotura aneurismática, con riesgo de resangrado, hidrocefalia e isquemia cerebral tardía."},
    physiopathology: {"pt": "O sangue subaracnóideo eleva pressão intracraniana e desencadeia inflamação/alterações vasculares que favorecem vasoespasmo e isquemia tardia.", "es": "La sangre subaracnoidea eleva la presión intracraneal y desencadena inflamación/cambios vasculares que favorecen vasoespasmo e isquemia tardía."},
