    exams: {"pt": ["TC de crânio sem contraste imediata", "Angio-TC/angiografia para aneurisma", "Punção lombar em cenário selecionado se TC não confirma", "ECG/troponina/eletrólitos"], "es": ["TC de cráneo sin contraste inmediata", "Angio-TC/angiografía para aneurisma", "Punción lumbar en escenario seleccionado si TC no confirma", "ECG/troponina/electrolitos"]},
    objectives: {"pt": ["Prevenir ressangramento", "Ocluir aneurisma precocemente", "Prevenir DCI", "Tratar hidrocefalia"], "es": ["Prevenir resangrado", "Excluir aneurisma precozmente", "Prevenir DCI", "Tratar hidrocefalia"]},
    actions: {"pt": ["1. Transferir para centro neurovascular/neuro-UTI", "2. Controlar hipertensão grave evitando hipotensão e grande variabilidade antes de tratar o aneurisma", "3. Ocluir aneurisma por coiling/clipping preferencialmente dentro de 24 h quando factível", "4. Iniciar nimodipina enteral precocemente; esquema clássico 60 mg a cada 4 h se tolerado", "5. Manter euvolemia; não induzir hipervolemia profilática", "6. Hidrocefalia sintomática pode exigir DVE", "7. Monitorar e tratar isquemia cerebral tardia de forma dirigida"], "es": ["1. Trasladar a centro neurovascular/neuro-UCI", "2. Controlar hipertensión grave evitando hipotensión y gran variabilidad antes de tratar el aneurisma", "3. Excluir aneurisma por coiling/clipping preferentemente dentro de 24 h cuando sea factible", "4. Iniciar nimodipino enteral precozmente; esquema clásico 60 mg cada 4 h si se tolera", "5. Mantener euvolemia; no inducir hipervolemia profiláctica", "6. Hidrocefalia sintomática puede requerir DVE", "7. Monitorizar y tratar isquemia cerebral tardía de forma dirigida"]},
    drugsFirstLine: {"pt": ["Nimodipina enteral precoce"], "es": ["Nimodipino enteral precoz"]},
    monitoring: {"pt": ["Neurológico seriado", "PA", "Sódio/balanço hídrico", "ECG", "DCI/vasoespasmo"], "es": ["Neurológico seriado", "PA", "Sodio/balance hídrico", "ECG", "DCI/vasoespasmo"]},
    complications: {"pt": ["Ressangramento", "Hidrocefalia", "DCI", "Hiponatremia", "Convulsões"], "es": ["Resangrado", "Hidrocefalia", "DCI", "Hiponatremia", "Convulsiones"]},
    doNotDo: {"pt": ["NÃO atrasar oclusão aneurismática", "NÃO usar hipervolemia profilática", "NÃO usar estatina/Mg IV rotineiramente para DCI"], "es": ["NO retrasar exclusión aneurismática", "NO usar hipervolemia profiláctica", "NO usar estatina/Mg IV rutinariamente para DCI"]},
    pearls: {"pt": ["AHA/ASA 2023 favorece tratamento do aneurisma em até 24 h", "Nimodipina enteral precoce melhora desfecho"], "es": ["AHA/ASA 2023 favorece tratar el aneurisma dentro de 24 h", "Nimodipino enteral precoz mejora el resultado"]},
    references: {"pt": ["https://professional.heart.org/en/science-news/2023-guideline-for-the-management-of-patients-with-aneurysmal-subarachnoid-hemorrhage/top-things-to-know", "https://pubmed.ncbi.nlm.nih.gov/37212182/"], "es": ["https://professional.heart.org/en/science-news/2023-guideline-for-the-management-of-patients-with-aneurysmal-subarachnoid-hemorrhage/top-things-to-know", "https://pubmed.ncbi.nlm.nih.gov/37212182/"]},
